// ---------- Zeichenwerkzeuge (Cartoon) ----------
let seed = 7; const R = () => { seed = (seed*16807) % 2147483647; return seed/2147483647; };
function cnv(w,h){ const c = document.createElement('canvas'); c.width = w; c.height = h; return [c, c.getContext('2d')]; }
function wob(cx,cy,rx,ry,n=30,amp=.03,rot=0){ const p=[], ph=R()*6; for(let i=0;i<n;i++){ const a=i/n*Math.PI*2, k=1+Math.sin(a*3+ph)*amp*.6+(R()-.5)*amp*.25;
  const x=Math.cos(a)*rx*k, y=Math.sin(a)*ry*k; p.push([cx + x*Math.cos(rot)-y*Math.sin(rot), cy + x*Math.sin(rot)+y*Math.cos(rot)]); } return p; }
function trace(x,p,closed=true){ x.beginPath(); p.forEach((q,i)=> i?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1])); if(closed) x.closePath(); }
const OUTL = '#3b2a3a';
function ink(x,p,closed=true,w=2.6){ x.lineJoin = x.lineCap = 'round'; trace(x,p,closed); x.strokeStyle = OUTL; x.lineWidth = w*1.3; x.stroke(); }
function bbox(p){ let a=1e9,b=1e9,c=-1e9,d=-1e9; p.forEach(q=>{a=Math.min(a,q[0]);b=Math.min(b,q[1]);c=Math.max(c,q[0]);d=Math.max(d,q[1]);}); return [a,b,c,d]; }
function darker(col, f=.85){ if (col[0] !== '#') return col; const n = parseInt(col.slice(1),16), r=(n>>16)&255, g=(n>>8)&255, b=n&255;
  return `rgb(${Math.round(r*f)},${Math.round(g*f*.96)},${Math.round(Math.min(255,b*f*1.04))})`; }
function pencil(x,p,col,hatch=true){   // flache Farbe mit Cel-Schatten
  const [a,b,c,d] = bbox(p);
  x.save(); trace(x,p); x.clip();
  x.fillStyle = hatch ? darker(col) : col; x.fillRect(a-2,b-2,c-a+4,d-b+4);
  if (hatch){ x.translate(-(c-a)*.08, -(d-b)*.1); trace(x,p); x.fillStyle = col; x.fill(); }
  x.restore();
}
function blob(x,circles,col){
  circles.forEach(([cx,cy,r]) => { x.beginPath(); x.arc(cx,cy,r,0,Math.PI*2); x.lineWidth = 7; x.strokeStyle = OUTL; x.stroke(); });
  x.save(); x.beginPath(); circles.forEach(([cx,cy,r]) => { x.moveTo(cx+r,cy); x.arc(cx,cy,r,0,Math.PI*2); }); x.clip();
  x.fillStyle = darker(col,.86); x.fillRect(0,0,x.canvas.width,x.canvas.height);
  x.fillStyle = col; circles.forEach(([cx,cy,r]) => { x.beginPath(); x.arc(cx - r*.1, cy - r*.15, r*.93, 0, Math.PI*2); x.fill(); });
  x.fillStyle = 'rgba(255,255,255,.4)'; circles.slice(0,2).forEach(([cx,cy,r]) => { x.beginPath(); x.ellipse(cx - r*.38, cy - r*.42, r*.24, r*.12, -.55, 0, 7); x.fill(); });
  x.restore();
}
function star(x,cx,cy,r,col,rot=0){ const p=[]; for(let i=0;i<10;i++){ const a=rot-Math.PI/2+i*Math.PI/5, rr=i%2?r*.48:r; p.push([cx+Math.cos(a)*rr, cy+Math.sin(a)*rr]); } pencil(x,p,col,true); ink(x,p,true,2.2);
  x.fillStyle = 'rgba(255,255,255,.55)'; x.beginPath(); x.ellipse(cx - r*.18, cy - r*.28, r*.16, r*.09, -.6, 0, 7); x.fill(); }
function grain(){}

