function tex(c){ if (texCache.has(c)) return texCache.get(c); const t = new THREE.CanvasTexture(c); t.anisotropy = 4; texCache.set(c,t); return t; }
function bill(c, w, parent=homeG, anchor=0){
  const h = w*c.height/c.width, g = new THREE.PlaneGeometry(w,h); g.translate(0, h/2 - anchor*h, 0);
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({map:tex(c), transparent:true, alphaTest:.06, side:THREE.DoubleSide}));
  parent.add(m); bills.push(m); fadeables.push(m); return m;
}
const shadowTex = (()=>{ const [c,x] = cnv(128,64); x.fillStyle='rgba(80,70,95,.28)'; x.beginPath(); x.ellipse(64,32,60,26,0,0,7); x.fill();
  x.strokeStyle='rgba(52,44,58,.25)'; x.lineWidth=1.5; for(let s=-60;s<70;s+=7){ x.beginPath(); x.moveTo(64+s,58); x.lineTo(64+s+24,8); x.stroke(); }
  x.globalCompositeOperation='destination-in'; x.beginPath(); x.ellipse(64,32,60,26,0,0,7); x.fill(); return tex(c); })();
function shadow(w, parent=homeG){ const m = new THREE.Mesh(new THREE.PlaneGeometry(w, w*.5), new THREE.MeshBasicMaterial({map:shadowTex, transparent:true, depthWrite:false}));
  m.rotation.x = -Math.PI/2; m.position.y = .012; parent.add(m); return m; }

