  ink(x, Array.from({length:20},(_,k)=>{ const t=k/19, X=(1-t)*(1-t)*117+2*(1-t)*t*94+t*t*117, Y=(1-t)*(1-t)*380+2*(1-t)*t*250+t*t*120; return [X,Y]; }), false, 2);
  ink(x, Array.from({length:20},(_,k)=>{ const t=k/19, X=(1-t)*(1-t)*107+2*(1-t)*t*82+t*t*107, Y=(1-t)*(1-t)*380+2*(1-t)*t*250+t*t*120; return [X,Y]; }), false, 2);
  [[140,280,.6],[72,240,-.7]].forEach(([lx,ly,rt])=>{ const p = wob(lx,ly,34,13,24,.05,rt); pencil(x,p,'#8fd88a'); ink(x,p); });
  const n = 6;
  for (let k=0;k<n;k++){ const a = k/n*Math.PI*2 + v*.3; const p = wob(110+Math.cos(a)*44, 108+Math.sin(a)*44, 40, 25, 26, .05, a); pencil(x,p,RAINBOW[(k+v)%6]); ink(x,p); }
  const cp = wob(110,108,26,26,24,.04); pencil(x,cp,'#ffe48a',false); ink(x,cp);
