const ROOT = [CX, FOOT];
function joint(parent, piv, ppiv){ const g = new THREE.Group(); g.position.set((piv[0]-ppiv[0])*K, (ppiv[1]-piv[1])*K, 0); g.userData.piv = piv; parent.add(g); return g; }
const J = {};
J.hips = joint(hop, [CX,1420], ROOT);
['legL','legR','bootL','bootR','skirt','torso'].forEach(n => J[n] = joint(J.hips, TP[n].piv, J.hips.userData.piv));
J.armL = joint(J.torso, TP.armL.piv, TP.torso.piv); J.armR = joint(J.torso, TP.armR.piv, TP.torso.piv);
