const camRight = () => new V3(Math.cos(az), 0, -Math.sin(az));
function startActivity(act){
  if (st.act && st.act.kind === 'animal' && st.act !== act){ st.act.ref.state = 'idle'; st.act.ref.timer = .4; }
  st.act = act; st.last = act; st.state = 'walk';
  if (act.kind === 'animal') act.ref.state = 'wait';
  // Seite wählen: links oder rechts vom Ziel (aus Kamerasicht), je nachdem, wo sie gerade steht
  const rt = camRight(); st.side = new V3().subVectors(st.pos, act.ref.pos).dot(rt) >= 0 ? 1 : -1;
  setStatus(act.go + ' …');
}
function chooseNext(){
  const opts = activities.filter(a => a !== st.last).sort((a,b)=> a.ref.pos.distanceTo(st.pos) - b.ref.pos.distanceTo(st.pos));
  startActivity(opts[Math.floor(Math.pow(Math.random(),1.7)*opts.length)]);
}
function approachPoint(act, out){
  const off = act.off ?? (act.kind === 'tree' ? 1.0 : act.kind === 'flower' ? .62 : .78);
  return out.copy(act.ref.pos).addScaledVector(camRight(), off*st.side).add(new V3(0,0,.05));
}
const angLerp = (a,b,t) => { let d = ((b-a+Math.PI)%(Math.PI*2)+Math.PI*2)%(Math.PI*2)-Math.PI; return a + d*t; };
const lerp = (a,b,t) => a + (b-a)*t;
let heartT = 0, blinkT = 2.2, blinkP = -1, twitchT = 2.5, lastAir = false;
const prevPos = new V3(); let vScr = 0, vy = 0, prevHopY = 0, prevArmL = 0, prevArmR = 0;
const ease = u => u*u*(3-2*u);
const clamp = (v,a,b) => Math.max(a, Math.min(b, v));
function updateGirl(dt, t){
  if (dt <= 0) return;
  st.timer -= dt;
  let walk = 0, lean = 0, headRot = Math.sin(t*1.1)*.035, jump = 0, sqY = 1, headBob = 0;
  let armL = Math.sin(t*1.3)*.04, armR = -Math.sin(t*1.3+.6)*.04;
  let hipSway = Math.sin(t*.8)*.02, breathe = Math.sin(t*2.4)*.012;
  let eye = 'open', mouth = 'smile', blush = 1, legLift = [0,0], legRot = [0,0];
  if (st.state === 'idle' && st.timer <= 0) chooseNext();
  if (st.state === 'walk'){
    approachPoint(st.act, st.approach);
    const d = new V3(st.approach.x - st.pos.x, 0, st.approach.z - st.pos.z), len = d.length();
    if (len < .05){
      const arrived = st.act;   // selbst angetippt? Dann z. B. Wissenskarte öffnen
      if (arrived === userPick){ userPick = null; if (arrived.onArrive) setTimeout(() => arrived.onArrive(arrived), 900); }
      st.state = 'act'; st.actT = 0; st.timer = st.act.kind === 'animal' ? 5.6 : 4.8;
      setStatus(st.act.doing + (st.act.mark || (st.act.kind === 'animal' ? ' ♡' : ' ✿')));
      if (st.act.kind === 'animal'){ const a = st.act.ref; a.state = 'play'; a.playA = Math.atan2(a.pos.x - st.pos.x, a.pos.z - st.pos.z); }
    } else {
      const sp = Math.min(1.3 + Math.max(0, len-3)*.3, 2.3, len*2.5);   // weite Wege etwas schneller
      st.pos.addScaledVector(d.normalize(), sp*dt);
      st.phase += dt*sp*8.2; walk = Math.min(1, sp/1.1);
      const s = d.dot(camRight()); if (Math.abs(s) > .12) st.face = s > 0 ? 1 : -1;
    }
  }
  const s = Math.sin(st.phase), c = Math.cos(st.phase);
  if (walk > 0){
    legRot = [.22*s*walk, -.22*s*walk];
    legLift = [Math.max(0, c)*walk, Math.max(0, -c)*walk];
    armL = .3*s*walk; armR = .3*s*walk;
    hipSway = -.05*s*walk; lean = .05*walk;
    jump = Math.abs(c)*.035*walk; breathe = .015*Math.cos(st.phase*2)*walk;
    headRot = -.035*s*walk;
  }
  if (st.state === 'act'){
    st.actT += dt; const T = st.actT;
    st.face = -st.side;
    const fade = Math.min(1, st.timer*2.5);
    if (st.act.kind !== 'animal'){
      const k = ease(Math.min(1, T*2.5)) * fade;
      lean = .2*k; headRot = -.17*k*st.face;
      if (st.act.marvel && T > .35 && T < 1.95){ eye = 'open'; mouth = 'o'; blush = 1.4; }   // staunen statt schnuppern
      else if (T > .35 && T < 1.95){
        eye = 'closed'; mouth = 'o'; blush = 1.3;
        headBob = Math.max(0, Math.sin((T-.35)*15))*.014;   // schnupper, schnupper
      } else if (T >= 1.95){
        eye = 'happy'; mouth = 'open'; blush = 1.9;
        const u = T - 1.95, kk = ease(Math.min(1, u*3))*fade;
        armL = 1.2*kk; armR = -1.3*kk;   // Hände vor der Brust zusammen
        jump = Math.abs(Math.sin(u*Math.PI/.36))*.08*(u < 1.08 ? 1 : 0)*fade;
        if (jump > .01) sqY = 1 + jump*.6;
        heartT -= dt;
        if (heartT <= 0){ heartT = .38;
          spawn(Math.random() < .7 ? fxTex.heart : fxTex.note, st.pos.clone().add(new V3((Math.random()-.5)*.5, 1.95, 0)), new V3((Math.random()-.5)*.15,.55,0), 1.7, .26); }
      }
      if (!st.act.marvel && T > .5 && T - dt <= .5) spawn(fxTex.sniff, st.pos.clone().add(new V3(0,2.25,0)).addScaledVector(camRight(), st.face*.4), new V3(0,.16,0), 2, .7, .245);
      if (Math.random() < dt*3){ const fp = st.act.ref.pos.clone().add(new V3(0, st.act.fxH ?? (st.act.kind === 'tree' ? 2.1 : 1.2), 0)).addScaledVector(camRight(), (Math.random()-.5)*.6);
        spawn(fxTex.star[(Math.random()*6)|0], fp, new V3((Math.random()-.5)*.25, -.25, 0), 2.2, .12); }
    } else {
      if (T < .32){ const u = T/.32; sqY = 1 - .16*Math.sin(u*Math.PI*.5); armL = .25; armR = -.25; mouth = 'open'; }
      else if (T < 2.42){
        const ph = ((T-.32)/.7) % 1, air = Math.sin(ph*Math.PI);
        jump = air*.5;
        sqY = air > .12 ? 1 + .1*air : 1 - .16*(1 - air/.12);
        const up = Math.min(1, air*2.5);
        armL = -1.1*up; armR = 1.1*up;
        legRot = [-.12*up, .12*up]; legLift = [.35*up, .35*up];
        eye = 'happy'; mouth = 'open'; blush = 1.6;
      } else if (T < 3.45){
        const u = (T-2.42)/1.03; st.spin = ease(u)*Math.PI*4; jump = Math.sin(u*Math.PI)*.14;
        armL = -.9; armR = .9; eye = 'happy'; mouth = 'open'; blush = 1.6;
      } else {
        st.spin = 0; eye = 'happy'; mouth = 'cat'; blush = 1.4;
        armL = Math.sin(T*9)*.3*fade; armR = -Math.sin(T*9)*.3*fade;
        jump = Math.abs(Math.sin(T*7))*.05*fade;
      }
      heartT -= dt;
      if (heartT <= 0){ heartT = .3; spawn(Math.random()<.5 ? fxTex.heart : fxTex.star[(Math.random()*6)|0], st.pos.clone().add(new V3((Math.random()-.5)*1.2, 1.7+Math.random()*.5, 0)), new V3(0,.6,0), 1.6, .2); }
    }
    if (st.timer <= 0){
      if (st.act.kind === 'animal'){ st.act.ref.state = 'idle'; st.act.ref.timer = .6; }
      st.state = 'idle'; st.timer = .9 + Math.random()*1.3; st.spin = 0; setStatus('schaut sich um …');
    }
  }
  // Blinzeln
  blinkT -= dt;
  if (blinkT <= 0 && blinkP < 0) blinkP = 0;
  if (blinkP >= 0){ blinkP += dt; const e = blinkP < .05 ? 'half' : blinkP < .11 ? 'closed' : blinkP < .16 ? 'half' : null;
    if (e && eye === 'open') eye = e; if (!e){ blinkP = -1; blinkT = 1.8 + Math.random()*3.2; } }
  faceSt.eye = eye; faceSt.mouth = mouth; faceSt.blush = lerp(faceSt.blush, blush, 1 - Math.pow(.02, dt));
  drawFaceOverlay();

  // Bewegung für Nachschwingen (die Zeichnung bleibt seitenrichtig; Richtung zeigt sich durch Neigung)
  const mv = new V3().subVectors(st.pos, prevPos); prevPos.copy(st.pos);
  vScr = lerp(vScr, mv.dot(camRight())/dt, 1 - Math.pow(.002, dt));
  st.faceS = lerp(st.faceS, st.face, 1 - Math.pow(.002, dt));
  const sx = st.spin ? Math.cos(st.spin) : 1;
  flip.scale.x = Math.abs(sx) < .05 ? .05*Math.sign(sx || 1) : sx;
  st.turn = lerp(st.turn, st.face*.2*walk, 1 - Math.pow(.02, dt));

  // Pose anwenden
  girl.position.copy(st.pos);
  const sm = 1 - Math.pow(.0006, dt), smA = 1 - Math.pow(.003, dt);
  hop.position.y = jump;
  hop.scale.y = lerp(hop.scale.y, sqY, 1 - Math.pow(1e-6, dt)); hop.scale.x = 1 + (1 - hop.scale.y)*.85;
  vy = (hop.position.y - prevHopY)/dt; prevHopY = hop.position.y;
  const air = hop.position.y > .03;
  if (lastAir && !air){ SP.ahoge.v -= 3.5; SP.skirtX.v += 1.2; SP.earL.v += 2; SP.earR.v -= 2; }
  lastAir = air;
  const dir = st.faceS;
  J.hips.rotation.z = lerp(J.hips.rotation.z, hipSway, sm);
  J.torso.rotation.z = lerp(J.torso.rotation.z, -lean*dir + .035*s*walk, sm);
  J.torso.scale.y = 1 + breathe;
  J.head.rotation.z = stepS(SP.head, headRot, dt);
  J.head.position.y = BASE.head.y + headBob;
  ['L','R'].forEach((k, i) => {
    const lg = J['leg'+k], bt = J['boot'+k], v = LEGV[k];
    lg.rotation.z = lerp(lg.rotation.z, legRot[i], sm);
    lg.scale.y = lerp(lg.scale.y, 1 - .3*legLift[i], sm);
    const th = lg.rotation.z, vx = v[0], vy2 = v[1]*lg.scale.y;
    bt.position.set(BASE['leg'+k].x + vx*Math.cos(th) - vy2*Math.sin(th), BASE['leg'+k].y + vx*Math.sin(th) + vy2*Math.cos(th) + legLift[i]*.025, 0);
    bt.rotation.z = th*.5;
  });
  J.armL.rotation.z = lerp(J.armL.rotation.z, armL, smA);
  J.armR.rotation.z = lerp(J.armR.rotation.z, armR, smA);
  const avL = (J.armL.rotation.z - prevArmL)/dt, avR = (J.armR.rotation.z - prevArmR)/dt;
  prevArmL = J.armL.rotation.z; prevArmR = J.armR.rotation.z;
  J.handL.rotation.z = stepS(SP.handL, clamp(-avL*.08, -.5, .5), dt);
  J.handR.rotation.z = stepS(SP.handR, clamp(-avR*.08, -.5, .5), dt);
  // Herz, Ohren und Rock schwingen nach
  const tilt = J.head.rotation.z + J.torso.rotation.z + J.hips.rotation.z;
  J.ahoge.rotation.z = stepS(SP.ahoge, clamp(-vScr*.3 - tilt*1.5, -.6, .6), dt);
  twitchT -= dt;
  if (twitchT <= 0){ twitchT = 2 + Math.random()*4; (Math.random() < .5 ? SP.earL : SP.earR).v += (Math.random() < .5 ? -1 : 1)*5; }
  J.earL.rotation.z = stepS(SP.earL, -tilt*.4, dt);
  J.earR.rotation.z = stepS(SP.earR, -tilt*.4, dt);
  J.skirt.rotation.z = stepS(SP.skirt, clamp(-vScr*.1 - J.hips.rotation.z*1.4, -.22, .22), dt);
  J.skirt.scale.x = 1 + stepS(SP.skirtX, clamp(-vy*.05, -.04, .12) + (st.spin ? .08 : 0), dt);
  gShadow.scale.setScalar(1 - jump*.6);
}

function updateAnimal(a, dt, t){
  a.timer -= dt; let moving = false, dir = null;
  if (a.state === 'idle'){ if (a.timer <= 0){ a.state = 'wander'; const ang = Math.random()*6.28, r = 2 + Math.random()*11; a.target.set(Math.cos(ang)*r, 0, Math.sin(ang)*r); } }
  else if (a.state === 'wander'){
    const d = new V3().subVectors(a.target, a.pos); d.y = 0;
    if (d.length() < .1){ a.state = 'idle'; a.timer = 1 + Math.random()*3; }
    else { dir = d.normalize(); a.pos.addScaledVector(dir, a.speed*dt); moving = true; }
  } else if (a.state === 'wait'){
    a.face = new V3().subVectors(st.pos, a.pos).dot(camRight()) > 0 ? 1 : -1;
  } else if (a.state === 'play'){
    a.playA += dt*2.3;
    const want = new V3(st.pos.x + Math.sin(a.playA)*.9, 0, st.pos.z + Math.cos(a.playA)*.55);
    dir = new V3().subVectors(want, a.pos); a.pos.lerp(want, 1 - Math.pow(.02, dt)); moving = true;
  }
  if (dir){ const s = dir.dot(camRight()); if (Math.abs(s) > .05) a.face = s > 0 ? 1 : -1; }
  a.ph += dt*a.hopF*(moving ? 1 : .15);
  a.g.position.copy(a.pos);
  a.body.position.y = moving ? Math.abs(Math.sin(a.ph))*a.hopH : 0;
  if (a.state === 'play' && a.kind === 'bear') a.body.position.y = Math.abs(Math.sin(t*4.5))*.22;
  a.fl.scale.x = lerp(a.fl.scale.x, a.face, 1 - Math.pow(.001, dt));
  a.body.scale.y = a.kind === 'bunny' ? 1 + (moving ? Math.cos(a.ph*2)*.07 : Math.sin(t*3+a.ph)*.015) : 1;
  a.body.rotation.z = a.kind === 'bear' && moving ? Math.sin(a.ph)*.1 : 0;
  if (a.kind === 'float'){ a.body.position.y = .35 + Math.sin(t*1.8 + a.ph)*.12; a.body.rotation.z = Math.sin(t*1.1 + a.ph)*.08; }
  if (a.appear !== undefined && a.appear < 1){   // Ankunft: aus dem Nichts wachsen, federn, dabei kurz wackeln
    const u = a.appear = Math.min(1, a.appear + dt/1.6);
    a.g.scale.setScalar(Math.max(.001, 1 - Math.cos(u*Math.PI*2.5)*Math.exp(-5*u)*(1-u)));
    a.body.rotation.z += Math.sin(u*26)*.22*(1-u);
  }
}

// ---------- Kamera & Eingabe ----------
const camT = new V3(0,1,0), ptrs = new Map(); let pinch0 = 0, downAt = null;
stage.addEventListener('pointerdown', e=>{ stage.setPointerCapture(e.pointerId); ptrs.set(e.pointerId,{x:e.clientX,y:e.clientY}); downAt = {x:e.clientX,y:e.clientY}; });
stage.addEventListener('pointermove', e=>{
  if (!ptrs.has(e.pointerId)) return; const p = ptrs.get(e.pointerId);
  if (ptrs.size === 1){ tAz -= (e.clientX-p.x)*.006; tEl = Math.max(.08, Math.min(.7, tEl + (e.clientY-p.y)*.003)); lastDrag = performance.now(); }
  ptrs.set(e.pointerId,{x:e.clientX,y:e.clientY});
  if (ptrs.size === 2){ const [a,b] = [...ptrs.values()], d = Math.hypot(a.x-b.x,a.y-b.y); if (pinch0) tDist = Math.max(3, Math.min(15, tDist*pinch0/d)); pinch0 = d; }
});
stage.addEventListener('pointerup', e=>{ ptrs.delete(e.pointerId); pinch0 = 0; if (downAt && Math.hypot(e.clientX-downAt.x, e.clientY-downAt.y) < 6) pick(e.clientX, e.clientY); downAt = null; });
stage.addEventListener('pointercancel', e=>{ ptrs.delete(e.pointerId); pinch0 = 0; downAt = null; });
stage.addEventListener('wheel', e=>{ e.preventDefault(); tDist = Math.max(3, Math.min(15, tDist*Math.exp(e.deltaY*.001))); }, {passive:false});
const ray = new THREE.Raycaster(), ndc = new THREE.Vector2();
function pick(x,y){
  ndc.set(x/innerWidth*2-1, -(y/innerHeight)*2+1); ray.setFromCamera(ndc, camera);
  const hit = ray.intersectObjects(pickables, false).find(h => { const u = h.uv, img = h.object.material.map.image; if (!u || !img.getContext) return true;
    const px = img.getContext('2d').getImageData(Math.floor(u.x*img.width), Math.floor((1-u.y)*img.height), 1, 1).data; return px[3] > 30; });
  if (hit){ userPick = hit.object.userData.act; startActivity(userPick); }
}
$('next').onclick = () => chooseNext();
$('pause').onclick = e => { paused = !paused; e.currentTarget.textContent = paused ? 'Weiter' : 'Pause'; };
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;

// Papierstruktur über allem
$('paper').style.backgroundImage = 'url(' + (()=>{ const [c,x] = cnv(256,256); const d = x.createImageData(256,256);
  for (let i=0;i<d.data.length;i+=4){ const v = 228 + Math.random()*27; d.data[i]=v; d.data[i+1]=v-1; d.data[i+2]=v-5; d.data[i+3]=255; }
  x.putImageData(d,0,0); x.strokeStyle='rgba(120,110,100,.1)'; for(let i=0;i<70;i++){ const a=Math.random()*256,b=Math.random()*256; x.beginPath(); x.moveTo(a,b); x.lineTo(a+Math.random()*40-20,b+Math.random()*40-20); x.stroke(); }
  return c.toDataURL(); })() + ')';

function resize(){ renderer.setSize(innerWidth, innerHeight); camera.aspect = innerWidth/innerHeight; camera.fov = camera.aspect < .8 ? 50 : 42; camera.updateProjectionMatrix(); if (camera.aspect < .8) tDist = 6.2; }
addEventListener('resize', resize); resize();

// ================= EIGENE FIGUREN: einscannen, speichern, mit allen teilen =================
// Zum Teilen mit allen ein Supabase-Projekt anlegen (siehe SUPABASE-EINRICHTEN.txt) und URL + anon-Schlüssel hier eintragen.
// Leer gelassen bleiben gescannte Figuren nur auf diesem Gerät.
const SUPA = {url:'', key:''};
const SHARE = !!(SUPA.url && SUPA.key), MAX_SHARED = 30, BUCKET = 'creatures';
// neue "publishable keys" (sb_…) nur als apikey senden, ältere anon-Schlüssel (JWT) zusätzlich als Bearer
const supaH = (extra={}) => ({apikey:SUPA.key, ...(SUPA.key.startsWith('sb_') ? {} : {Authorization:'Bearer '+SUPA.key}), ...extra});
const uuid = () => crypto.randomUUID ? crypto.randomUUID() : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, ch => { const r = Math.random()*16|0; return (ch === 'x' ? r : (r&3|8)).toString(16); });

// lokale Ablage (IndexedDB): eigene Figuren und die zuletzt geladenen geteilten Figuren, damit sie auch offline da sind
const idb = (() => {
  let p; const open = () => p || (p = new Promise((ok, bad) => { const r = indexedDB.open('rainbow-stars', 2);
    r.onupgradeneeded = () => { const db = r.result; if (!db.objectStoreNames.contains('creatures')) db.createObjectStore('creatures', {keyPath:'id'});
      if (!db.objectStoreNames.contains('progress')) db.createObjectStore('progress', {keyPath:'k'}); };
    r.onsuccess = () => ok(r.result); r.onerror = () => bad(r.error); }));
  const run = (store, mode, fn) => open().then(db => new Promise((ok, bad) => { const tx = db.transaction(store, mode), r = fn(tx.objectStore(store));
    tx.oncomplete = () => ok(r && r.result); tx.onerror = () => bad(tx.error); }));
  return {all: () => run('creatures', 'readonly', s => s.getAll()).catch(() => []), put: v => run('creatures', 'readwrite', s => s.put(v)).catch(() => {}),
    del: id => run('creatures', 'readwrite', s => s.delete(id)).catch(() => {}),
    getP: k => run('progress', 'readonly', s => s.get(k)).then(r => r && r.v).catch(() => undefined),
    setP: (k, v) => run('progress', 'readwrite', s => s.put({k, v})).catch(() => {})};
})();

// --- Figuren in der Welt ---
const world = new Map();   // id -> Tier-Objekt (null, solange das Bild noch lädt)
async function blobCanvas(blob){ const b = await createImageBitmap(blob); const [c,x] = cnv(b.width, b.height); x.drawImage(b,0,0); if (b.close) b.close(); return c; }
function arrivalFx(a){
  for (let i=0;i<26;i++){ const ang = i/26*Math.PI*2;
    spawn(fxTex.star[i%6], a.pos.clone().add(new V3(Math.cos(ang)*.55, .08 + (i%5)*.12, Math.sin(ang)*.55)), new V3(-Math.sin(ang)*.5, .8 + Math.random()*.5, Math.cos(ang)*.5), 1.8 + Math.random(), .12); }
  setTimeout(() => { for (let i=0;i<5;i++) spawn(fxTex.heart, a.pos.clone().add(new V3((Math.random()-.5)*.6, .9 + Math.random()*.3, 0)), new V3((Math.random()-.5)*.2, .5, 0), 2, .16); }, 1300);
}
async function showCreature(rec, {near=false, arrive=false}={}){
  if (world.has(rec.id)) return world.get(rec.id); world.set(rec.id, null);
  let c; try { c = await blobCanvas(rec.blob); } catch(e){ world.delete(rec.id); console.warn('Figurenbild nicht lesbar', e); return null; }
  if (!world.has(rec.id)) return null;   // in der Zwischenzeit entfernt
  const w = Math.min(1.4, .95*c.width/c.height), ang = Math.random()*Math.PI*2;
  const pos = near ? st.pos.clone().addScaledVector(camRight(), (Math.random() < .5 ? -1 : 1)*1.9).add(new V3(Math.sin(az)*.6, 0, Math.cos(az)*.6))
                   : new V3(Math.cos(ang), 0, Math.sin(ang)).multiplyScalar(3 + Math.random()*8);
  const wid = W[rec.world] ? rec.world : 'home';
  const a = addCreature({name:rec.name, c, w, kind:rec.kind, pos, rnd:Math.random, appear: arrive ? 0 : undefined, wid});
  world.set(rec.id, a);
  if (arrive && wid === worldId){ arrivalFx(a); setStatus(rec.name + ' ist angekommen! ✦'); setTimeout(() => { if (animals.includes(a)) startActivity(a.act); }, 2400); }
  return a;
}
function removeCreature(id){
  const a = world.get(id); world.delete(id); if (!a) return;
  if (st.act && st.act.ref === a){ st.act = null; st.state = 'idle'; st.timer = .6; }
  if (st.last && st.last.ref === a) st.last = null;
  a.g.parent.remove(a.g);
  [[animals,a],[W[a.wid].acts,a.act],[W[a.wid].picks,a.mesh],[bills,a.bb],[fadeables,a.mesh]].forEach(([arr,v]) => { const i = arr.indexOf(v); if (i >= 0) arr.splice(i,1); });
  const img = a.mesh.material.map.image, tx = texCache.get(img); if (tx){ tx.dispose(); texCache.delete(img); }
}

// --- Teilen über Supabase (REST, ohne Zusatzbibliothek) ---
async function uploadCreature(rec){
  if (!SHARE || rec.uploaded || !navigator.onLine) return false;
  const path = rec.id + '.png';
  const up = await fetch(`${SUPA.url}/storage/v1/object/${BUCKET}/${path}`, {method:'POST', headers:supaH({'Content-Type':'image/png'}), body:rec.blob});
  if (!up.ok && !/duplicate|exists/i.test(await up.text())) throw new Error('Bild-Upload: ' + up.status);
  const ins = await fetch(`${SUPA.url}/rest/v1/creatures`, {method:'POST', headers:supaH({'Content-Type':'application/json', Prefer:'return=minimal'}),
    body:JSON.stringify({id:rec.id, name:rec.name, kind:rec.kind, image_path:path})});
  if (!ins.ok && ins.status !== 409) throw new Error('Eintrag: ' + ins.status);
  rec.uploaded = true; delete rec.shareError; await idb.put(rec); return true;
}
const shareEvt = (rec, state, msg) => dispatchEvent(new CustomEvent('rs:share', {detail:{id:rec.id, name:rec.name, state, msg}}));
function shareCreature(rec){
  if (!SHARE) return;
  if (!navigator.onLine){ shareEvt(rec, 'offline'); return; }
  shareEvt(rec, 'sending');
  uploadCreature(rec).then(done => { if (done) shareEvt(rec, 'uploaded'); })
    .catch(e => { console.warn('Teilen fehlgeschlagen, neuer Versuch später', e); rec.shareError = String(e.message || e); idb.put(rec); shareEvt(rec, 'error', rec.shareError); });
}
let syncing = false;
async function syncShared(first){
  if (!SHARE || !navigator.onLine || syncing) return; syncing = true;
  try {
    const res = await fetch(`${SUPA.url}/rest/v1/creatures?select=id,name,kind,image_path,created_at&approved=eq.true&order=created_at.desc&limit=${MAX_SHARED}`, {headers:supaH(), cache:'no-store'});
    if (!res.ok) throw new Error('Liste: ' + res.status);
    const rows = await res.json(), ids = new Set(rows.map(r => r.id)), local = await idb.all();
    // fremde Figuren, die nicht mehr freigegeben (oder zu alt) sind, verschwinden wieder
    for (const r of local) if (!r.mine && !ids.has(r.id)){ removeCreature(r.id); idb.del(r.id); }
    for (const r of local) if (r.mine && ids.has(r.id) && !r.approved){ r.approved = true; idb.put(r); dispatchEvent(new CustomEvent('rs:share', {detail:{id:r.id, name:r.name, state:'approved'}})); }
    const known = new Set(local.map(r => r.id));
    for (const row of rows.reverse()){
      if (known.has(row.id)) continue;
      const img = await fetch(`${SUPA.url}/storage/v1/object/public/${BUCKET}/${encodeURIComponent(row.image_path)}`); if (!img.ok) continue;
      const rec = {id:row.id, name:String(row.name || 'Freund').slice(0,24), kind:['bear','float'].includes(row.kind) ? row.kind : 'bunny', blob:await img.blob(), mine:false, created:Date.parse(row.created_at) || Date.now()};
      await idb.put(rec); showCreature(rec, {arrive:!first});
    }
  } catch(e){ console.warn('Geteilte Figuren konnten nicht geladen werden', e); }
  syncing = false;
}
function retryUploads(){ idb.all().then(recs => recs.filter(r => r.mine && !r.uploaded && (r.world || 'home') === 'home').forEach(r => uploadCreature(r).catch(() => {}))); }
// erst wenn alle Skripte (auch die Zusatz-Welten) geladen sind, die gespeicherten Figuren einsetzen
addEventListener('DOMContentLoaded', () => idb.all().then(recs => { recs.sort((a,b) => a.created - b.created).forEach(r => showCreature(r)); retryUploads(); syncShared(true); }));
addEventListener('online', () => { retryUploads(); syncShared(false); });
setInterval(() => { if (document.visibilityState === 'visible') syncShared(false); }, 90000);

// --- Scanner: Foto -> Ausschnitt -> Papier entfernen -> Figur ---
function photoCanvas(file){ return new Promise((ok, bad) => { const u = URL.createObjectURL(file), im = new Image();
  im.onload = () => { const k = Math.min(1, 2400/Math.max(im.naturalWidth, im.naturalHeight)), [c,x] = cnv(Math.round(im.naturalWidth*k), Math.round(im.naturalHeight*k));
    x.drawImage(im, 0, 0, c.width, c.height); URL.revokeObjectURL(u); ok(c); };
  im.onerror = () => { URL.revokeObjectURL(u); bad(new Error('Bild nicht lesbar')); }; im.src = u; }); }
function dilate(m, W, H){ const o = new Uint8Array(m.length);
  for (let y=0;y<H;y++) for (let x=0;x<W;x++){ const i = y*W+x; if (!m[i]) continue; o[i] = 1; if (x>0) o[i-1] = 1; if (x<W-1) o[i+1] = 1; if (y>0) o[i-W] = 1; if (y<H-1) o[i+W] = 1; }
  return o; }
// Schneidet die Zeichnung vom Papier aus.
// sens 0–100: wie zart ein Strich sein darf, damit er noch zur Figur zählt (rechts = auch ganz zarte Striche).
// Zwei Durchgänge: erst grob die Figur finden, dann nur um sie herum in hoher Auflösung ausschneiden.
function cutout(src, r, sens, boost = true){
  const first = cutPass(src, r, sens, 720); if (!first) return null;
  const pad = Math.max(first.bw, first.bh)*.08, x0 = Math.max(r.x, first.bx - pad), y0 = Math.max(r.y, first.by - pad);
  const r2 = {x:x0, y:y0, w:Math.min(r.x + r.w, first.bx + first.bw + pad) - x0, h:Math.min(r.y + r.h, first.by + first.bh + pad) - y0};
  const fine = r2.w*r2.h < r.w*r.h*.8 ? cutPass(src, r2, sens, 1100, first) : null;
  return finishCut(fine || first, boost);
}
